import { Component, Injectable, inject, signal } from '@angular/core';

@Injectable({ providedIn: 'root' })
class AuthService { readonly user = signal<string | null>(null); }

@Injectable()
class CheckoutDraft { readonly note = signal(''); }

@Component({
  selector: 'checkout-page',
  providers: [CheckoutDraft],
  template: `<p>User: {{ auth.user() ?? 'guest' }}</p>
             <input [value]="draft.note()"
                    (input)="draft.note.set($any($event.target).value)">`,
})
class CheckoutPage {
  readonly auth = inject(AuthService);
  readonly draft = inject(CheckoutDraft);
}
```

