import { Component, Injectable, inject } from '@angular/core';

@Injectable({ providedIn: 'root' })
class GreetingService { message(name: string) { return `Hello, ${name}`; } }

@Component({
  selector: 'greeting-button',
  template: `<button (click)="greet()">Greet</button><p>{{ text }}</p>`,
})
class GreetingButton {
  private readonly greetings = inject(GreetingService);
  text = '';

  greet() {
    this.text = this.greetings.message('Mina');
  }
}
